//! Generated by `gpuicn init` and `gpuicn theme`; change the theme with `gpuicn theme set` or
//! `gpuicn theme import`, or edit `assets/theme.css` and keep this file.

use super::theme::{Appearance, ThemeMode, UiFonts, UiTheme};

/// The app's shadcn theme CSS (`:root` is light, `.dark` is dark).
pub const CSS: &str = include_str!("../../assets/theme.css");
/// The appearance gpuicn.toml selects; `System` follows the OS.
pub const APPEARANCE: Appearance = Appearance::System;

/// 正文字体族：`assets/fonts` 下加载的 HarmonyOS Sans。
///
/// Light(300)/Regular(400)/Bold(700) 三个字重共用这个族名；Thin(250) 与
/// Black(900) 在字体内部是独立族名（`HarmonyOS Sans Thin` / `HarmonyOS Sans
/// Black`），需要时可按名单独指定。
pub const BODY_FONT: &str = "HarmonyOS Sans";

/// 等宽字体族。HarmonyOS Sans 不带等宽字面，按平台回落到系统自带等宽字体。
pub const MONO_FONT: &str = if cfg!(target_os = "macos") {
    "Menlo"
} else if cfg!(target_os = "windows") {
    "Consolas"
} else {
    "DejaVu Sans Mono"
};

/// 从 CSS 解析主题，并套用应用自己的字体族。
fn theme(mode: ThemeMode) -> UiTheme {
    let mut theme = UiTheme::from_shadcn_css(CSS, mode).expect("assets/theme.css parses");
    theme.fonts = UiFonts {
        body: BODY_FONT.into(),
        heading: BODY_FONT.into(),
        mono: MONO_FONT.into(),
    };
    theme
}

/// The light theme from `assets/theme.css`.
pub fn light() -> UiTheme {
    theme(ThemeMode::Light)
}

/// The dark theme from `assets/theme.css`.
pub fn dark() -> UiTheme {
    theme(ThemeMode::Dark)
}
